mapper.select:
SELECT T.TRN_SEQ, T.TRN_DT, T.TRN_TP_CD, T.TRN_AMT, T.BAL_AMT, T.REMARK
FROM TB_TRN_HIST T
WHERE T.ACCT_NO = #{acctNo}

  AND T.TRN_DT >= #{fromDt}


  AND T.TRN_DT <= #{toDt}

ORDER BY T.TRN_DT DESC, T.TRN_SEQ DESC

mapper.update:
UPDATE TB_ACCT
SET BAL_AMT = BAL_AMT - #{trnAmt},
    UPD_DT = SYSDATE
WHERE ACCT_NO = #{acctNo}
  AND BAL_AMT >= #{trnAmt}
  AND STAT_CD = '01'

mapper.insert:
INSERT INTO TB_TRN_HIST (
  ACCT_NO, TRN_DT, TRN_TP_CD, TRN_AMT, CNTR_ACCT_NO, REMARK
) VALUES (
  #{acctNo}, SYSDATE, '11', #{trnAmt}, #{toAcctNo}, '이체'
)
